/* v94.6.1 · 4 道占位题补齐（t4-hf47/48/57/85，此前仅存 title/topic）
 * passage + 三问 subqs 均为 AI 撰写（_src:'ai'）→ 界面显示 ✎ AI
 * 应用方式：applyFix 遍历 bank[4]，按 id 覆盖空缺字段
 */
window.SIELE_ORAL_EXT_FIX_T4_HOLES = {
"t4-hf47": {
 passage:"El desarrollo económico de las últimas décadas ha sacado de la pobreza extrema a miles de millones de personas, sobre todo en Asia. Sin embargo, la brecha entre países y dentro de cada país sigue creciendo: la riqueza se concentra y el acceso a la educación, la sanidad y las oportunidades depende cada vez más del punto de partida. Los organismos internacionales debaten cómo repartir mejor el crecimiento y si el modelo actual es sostenible para el planeta.",
 passageZh:"近几十年经济发展让数十亿人摆脱极端贫困，亚洲尤为显著。但国家之间与各国内部的差距仍在扩大：财富日益集中，教育、医疗与机会的获取越来越取决于出身。国际组织正在讨论如何更好分配增长成果，以及现行模式对地球是否可持续。",
 passageSrc:"材料基于国际发展议题公开报道撰写",_src:"ai",
 subqs:[
  {q:"¿Qué relación ve usted entre el desarrollo económico y la pobreza?",
   keys:["crecimiento","desigualdad","empleo","educación","reparto"],
   model:"Yo veo una relación fuerte pero no automática. El crecimiento económico sacó de la pobreza a miles de millones de personas, sobre todo en Asia: sin desarrollo no hay empleo ni recursos para sanidad o educación. Ahora bien, el crecimiento por sí solo no garantiza nada: si la riqueza se concentra en pocas manos, un país puede ser más rico y seguir teniendo pobreza. La clave está en el reparto: impuestos justos, educación pública y sanidad universal convierten el crecimiento en progreso real. En definitiva, el desarrollo es la condición necesaria, pero el combate contra la pobreza exige, además, políticas que repartan lo que crece."},
  {q:"¿Qué causa la desigualdad entre las personas de un mismo país? ¿Qué se puede hacer?",
   keys:["educación","oportunidades","salario","impuestos","origen"],
   model:"La desigualdad dentro de un país nace de varias causas que se refuerzan entre sí. La principal es el punto de partida: nacer en un barrio con buenas escuelas o en uno abandonado marca toda la trayectoria, porque la educación es hoy el gran divisor. Le siguen el mercado laboral, con sueldos muy altos y muy bajos conviviendo, y la herencia, que acumula ventajas generación tras generación. ¿Qué se puede hacer? Yo destacaría tres cosas: invertir en educación pública de calidad, que iguala el punto de partida; un sistema fiscal que grave más a las grandes fortunas; y salarios mínimos dignos. No se trata de que todos ganen lo mismo, sino de que las oportunidades no dependan del código postal."},
  {q:"¿Es posible un mundo sin pobreza? ¿Qué haría falta?",
   keys:["voluntad","recursos","educación","cooperación","justicia"],
   model:"Yo creo que es posible, y no es una utopía ingenua: la humanidad ya redujo la pobreza extrema como nunca en la historia, así que el camino existe. ¿Qué haría falta? Tres cosas. Primera, voluntad política real: los recursos del planeta alcanzan, lo que falta es repartirlos y combatir la corrupción que los desvía. Segunda, cooperación internacional seria, porque ningún país se salva solo de las crisis, las migraciones forzadas o el clima. Y tercera, atacar las raíces: educación, sanidad y oportunidades para mujeres y niñas, que son la palanca con más efecto demostrado. Un mundo sin pobreza extrema no es cuestión de milagros, sino de decisiones sostenidas en el tiempo."}
 ]
},
"t4-hf48": {
 passage:"Con la expansión de las redes sociales y la inteligencia artificial, la desinformación alcanza niveles sin precedentes: bulos sanitarios, imágenes falsas de alta calidad y titulares engañosos circulan más rápido que las noticias verificadas. Las plataformas anuncian sistemas de verificación y etiquetado, mientras los educadores piden enseñar a los ciudadanos a comprobar las fuentes como una competencia básica del siglo XXI.",
 passageZh:"随着社交平台与人工智能普及，虚假信息达到空前规模：健康谣言、以假乱真的图像与误导性标题的传播速度超过经核实的新闻。各平台宣布推出核查与标注系统，教育界则呼吁把核对信息来源作为 21 世纪基本素养来教授。",
 passageSrc:"材料基于信息核查与平台治理公开报道撰写",_src:"ai",
 subqs:[
  {q:"¿Cree que la información en Internet es fiable? ¿Por qué?",
   keys:["fuente","verificar","bulo","medio","crédito"],
   model:"Yo diría que es fiable a ratos: internet tiene de todo, desde los mejores análisis hasta el engaño más burdo. La red misma no garantiza nada, porque cualquiera puede publicar sin control y el algoritmo premia lo viral, que no siempre es lo verdadero. Mi criterio práctico es mirar tres cosas: quién firma, si otros medios serios lo recogen y si el titular respeta al contenido. Si una noticia solo aparece en cuentas anónimas y apela a la indignación, desconfío. La información en internet es una herramienta potente, pero exige usuario crítico: la fiabilidad ya no la da el canal, la da la comprobación."},
  {q:"¿Cómo distinguir una noticia falsa de una verdadera? Dé ejemplos.",
   keys:["contrastar","fuente oficial","fecha","autor","sesgo"],
   model:"Hay varias señales de alarma que funcionan bien. Primera, la fuente: comprueba quién lo firma; un medio con nombre y sección distinta a una cuenta anónima con un vídeo sin origen. Segunda, el contraste: busca el dato en dos o tres medios serios distintos; si nadie más lo recoge, sospecha. Tercera, la fecha: muchas veces una noticia verdadera pero vieja se recicla para indignar. Y cuarta, el estilo: mayúsculas, «COMPÁRTELO ANTES DE QUE LO BORREN» y fotos borrosas son el uniforme del bulo. Por ejemplo, durante desastres circulan imágenes de otras catástrofes presentadas como actuales; una búsqueda inversa de la imagen las desenmascara en segundos."},
  {q:"¿Quién debe responsabilizarse de combatir la desinformación: las plataformas, el gobierno o los ciudadanos?",
   keys:["plataforma","ley","educación","responsabilidad","equilibrio"],
   model:"Yo creo que la respuesta es los tres, cada uno en su parcela. Las plataformas, porque construyen el algoritmo que amplifica: deben frenar lo viral falso, etiquetar y dar visibilidad a lo verificado, sin esconderse tras decir que «solo son un canal». Los gobiernos, porque deben poner límites legales claros que protejan el debate sin convertir la ley en censura; ahí está el equilibrio difícil. Y los ciudadanos, porque ninguna tecnología sustituye al criterio personal: verificar antes de compartir es el gesto individual con más impacto. Si tuviera que jerarquizar, yo empezaría por la educación ciudadana, porque un público formado es el antiviral más eficaz contra cualquier bulo, hoy y dentro de veinte años."}
 ]
},
"t4-hf57": {
 passage:"Pese a los avances legales, la igualdad entre hombres y mujeres en la familia dista de ser real: las encuestas de uso del tiempo muestran que las mujeres dedican el doble de horas a las tareas del hogar y al cuidado de hijos y mayores, incluso cuando trabajan fuera a jornada completa. Los expertos hablan de corresponsabilidad como el siguiente paso del proyecto de igualdad, y algunos países prueban permisos de paternidad más largos para equilibrar el reparto desde el nacimiento.",
 passageZh:"尽管法律不断进步，家庭内部的男女平等仍远未实现：时间使用调查显示，即使女性在外全职工作，她们承担家务与照护子女老人的时长仍是男性的两倍。专家提出「共同承担责任」是平等事业的下一步，一些国家正通过延长男性育儿假来从孩子出生起平衡分工。",
 passageSrc:"材料基于时间使用与家庭照护公开调查撰写",_src:"ai",
 subqs:[
  {q:"¿Existe hoy la igualdad entre hombres y mujeres en las familias de su país?",
   keys:["reparto","tareas","cuidado","costumbre","cambiar"],
   model:"Yo diría que la igualdad existe en el discurso, pero no del todo en la práctica. En las leyes y en las intenciones, casi nadie discute ya que ambos miembros son iguales; pero en los datos del día a día, las mujeres siguen dedicando el doble de horas a la casa y al cuidado, aunque trabajen fuera igual que sus parejas. Ha cambiado mucho en una generación: los padres de hoy cambian pañales y van a las reuniones del colegio, algo impensable antes. Pero la carga mental, la de organizar y recordar todo, sigue recayendo en ellas. En definitiva: avanzamos bien, pero la igualdad real se mide en el reparto diario, y ahí queda camino."},
  {q:"¿Por qué las tareas del hogar siguen repartiéndose de forma desigual? ¿Cómo cambiarlo?",
   keys:["costumbre","educación","ejemplo","acuerdo","visible"],
   model:"La desigualdad doméstica sobrevive por inercia cultural más que por convicción: crecimos viendo hogares donde la madre lo hacía todo, y esa imagen se repite sin examen, además reforzada por la idea de que «ella lo hace mejor». Se cambia, en mi opinión, con tres cosas. Primera, hacerlo visible: muchas tareas invisibles solo cambian cuando se cuentan, por eso las encuestas de tiempo son tan útiles. Segunda, el acuerdo explícito en pareja: repartir por escrito al principio suena friki, pero evita años de reproches. Y tercera, la educación de los hijos: que niños y niñas hagan las mismas tareas en casa, porque lo que se aprende de pequeño no se discute de adulto. La costumbre solo se rompe con práctica nueva y sostenida."},
  {q:"¿Qué papel deben jugar las empresas y el gobierno para facilitar la igualdad en casa?",
   keys:["permiso","horario","teletrabajo","ley","conciliación"],
   model:"Un papel importante, porque la desigualdad en casa no se arregla solo dentro de casa. El gobierno debe diseñar permisos que de verdad se usen: los permisos de paternidad largos e intransferibles son la medida con más evidencia, porque obligan a que el padre esté desde el principio y eso marca el reparto de toda la vida. También horarios laborales humanos, porque nadie puede corresponsabilizarse saliendo del trabajo a las nueve. Las empresas, por su parte, deben ofrecer flexibilidad real a ambos sexos: el teletrabajo solo lo piden las mujeres cuando penaliza su carrera, y eso reproduce el desequilibrio. En definitiva, la igualdad doméstica necesita arquitectura legal y empresarial que la haga posible, no solo buena voluntad individual."}
 ]
},
"t4-hf85": {
 passage:"Las plataformas de colaboración —compartir coche, herramientas, viviendas o comidas— mueven ya miles de millones de euros al año. Sus defensores las presentan como una economía más eficiente y sostenible que aprovecha recursos ociosos, mientras sus críticos la describen como un capitalismo disfrazado: grandes empresas tecnológicas que cobran comisiones sin derechos laborales ni fiscales claros para quienes trabajan en ellas. El debate regulador sigue abierto en toda Europa.",
 passageZh:"共享出行、工具、住房、餐食等协作平台年交易额已达数十亿欧元。支持者称其更高效、更可持续，能盘活闲置资源；批评者则认为这是变相资本主义：科技巨头抽成，而劳动者缺少明确劳动与税收保障。欧洲各地监管辩论仍在进行。",
 passageSrc:"材料基于平台经济监管公开报道撰写",_src:"ai",
 subqs:[
  {q:"¿La economía colaborativa es un avance social o un nuevo capitalismo? ¿Por qué?",
   keys:["compartir","plataforma","comisión","regulación","trabajador"],
   model:"Yo diría que es las dos cosas a la vez, y esa ambigüedad es justo el problema. Como avance, es real: aprovecha recursos que dormían —un coche aparcado, una habitación vacía— y permite a familias comunes ingresar dinero extra, además de reducir el consumo nuevo. Pero como capitalismo nuevo, también: detrás de las apps hay gigantes tecnológicos que cobran comisiones considerables, evitan responsabilidades laborales y compiten con ventaja injusta contra quien sí paga impuestos y cotiza. Mi conclusión es que la idea es buena y el modelo, imperfecto: la economía colaborativa será un avance social cuando la regulación iguale las reglas —fiscales y laborales—, porque compartir no debería ser sinónimo de trabajar sin derechos."},
  {q:"¿Ha utilizado usted servicios de economía colaborativa? ¿Qué experiencia tuvo?",
   keys:["aplicación","compartir coche","alojamiento","precio","confianza"],
   model:"Sí, los uso con frecuencia y mi experiencia es buena en general. Compartir coche en viajes largos me ha salido mucho más barato que el tren y, de paso, he conocido gente interesante; los sistemas de bicicletas compartidas cambiaron mi forma de moverme por la ciudad; y en alojamiento, las plataformas ofrecen opciones con encanto que ningún hotel iguala. Ahora bien, también he visto las caras oscuras: precios que suben en fechas señaladas, anuncios que no se corresponden con la realidad y la sensación de que la plataforma solo aparece para cobrar, nunca cuando hay un problema. Para mí el balance es positivo, pero depende de que la plataforma garantice mínimos: seguro, revisión de anuncios y un servicio de atención que responda."},
  {q:"¿Qué debería regular el gobierno en la economía colaborativa? ¿Por qué?",
   keys:["impuestos","seguro","derechos","competencia","vivienda"],
   model:"Yo regularía cuatro frentes. Primero, los impuestos: quien ingresa dinero alquilando su piso o su coche debe tributar como cualquier actividad económica; sin eso, es competencia desleal contra hoteles y taxis que sí pagan. Segundo, los derechos de quien trabaja en plataformas de reparto o transporte: si la persona depende de la app para vivir, necesita cotización, seguro y límites de jornada, sea cual sea su contrato. Tercero, la seguridad: anuncios verificados, seguros de responsabilidad y una vía real de reclamación. Y cuarto, el impacto en la vivienda, limitando las plazas turísticas en barrios saturados. La economía colaborativa no hay que asfixiarla, pero tampoco dejarla en una zona sin ley: las reglas claras protegen al trabajador, al usuario y al propio modelo."}
 ]
}
};
